def position(n,above):
 py=85 if above else 210
 paths=AXES+[path([(45,85),(430,250)]),path([(220,py),(220,240)]),path([(80,160),(220,160)],dash=True),path([(80,py),(220,py)],dash=True)]
 labels=AXIS_LABELS+[(37,76,'A'),(436,254,'B'),(225,py-8,'P(x₁,y₁)'),(225,153,'Q(x₁,y₂)'),(214,265,'M'),(58,py+5,'y₁'),(58,165,'y₂'),(214,285,'x₁')]
