EXAMPLES=[]
for n,q,steps,ans,pages in [
('16','Determine whether P(10,−6) is above or below 9x+10y−3 = 0, and whether P and the origin are on the same or opposite sides.',['Set F(x,y) = 9x+10y−3. The coefficient of y is b = 10 > 0.','Evaluate F(10,−6) = 90−60−3 = 27 > 0.','Because b > 0, this positive result means P is above the line.','Check directly: at x = 10, the line has y = (3−90)/10 = −87/10 = −8.7, while P has y = −6 > −8.7.','At the origin, F(0,0) = −3 < 0.','The product of the two evaluated values is 27(−3) = −81 < 0, so the signs are opposite.','Therefore P is above the line and P and the origin lie on opposite sides.'],'P is above the line; P and the origin are on opposite sides.',[193,194]),
('17','Find the perpendicular distance from P(2,3) to 7x+3y−9 = 0.',['Read the coefficients a = 7, b = 3, c = −9.','The normal vector (7,3) is nonzero and has length √(49+9) = √58.','Evaluate the line expression at P: 7·2+3·3−9 = 14.','Use d = |ax₁+by₁+c|/√(a²+b²).','Thus d = 14/√58 units, a positive distance.','Independently, the perpendicular foot is P−(14/58)(7,3) = (9/29,66/29).','Check this foot lies on the line: 7(9/29)+3(66/29)−9 = 261/29−9 = 0. Its displacement from P has length 14/√58.'],'14/√58 units.',[194])]:
 EXAMPLES.append({'num':n,'title':'Point Position and Distance','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'pageStart':min(pages),'pageEnd':max(pages),'verification':'Complete source question and working visually checked'}]})
